import { setupWorker } from "msw/browser";
import { handlers } from "./handlers";

function computeBase() {
  // 1차: 환경변수 (CRA/Vite)
  const viteBase =
    (typeof import.meta !== "undefined" &&
      import.meta.env &&
      import.meta.env.BASE_URL) || "";
  const craBase =
    (typeof process !== "undefined" &&
      process.env &&
      process.env.PUBLIC_URL) || "";

  let picked = craBase || viteBase;

  // 2차: 환경변수 못 잡으면 URL에서 첫 세그먼트로 추정 (/woodenpages/ 같은 거)
  if (!picked) {
    const p =
      (typeof window !== "undefined" &&
        window.location &&
        window.location.pathname) ||
      "/";
    const seg = p.split("/").filter(Boolean)[0]; // ['woodenpages', ...] → 'woodenpages'
    picked = seg ? `/${seg}/` : "/";
  }

  const normalized = picked.endsWith("/") ? picked : picked + "/";

  try {
    console.log("[MSW] base:", normalized);
  } catch {}

  return normalized;
}

const base = computeBase();

export const worker = setupWorker(...handlers);

export const workerOptions = {
  serviceWorker: {
    url: `${base}mockServiceWorker.js`,  // ← 이제 /woodenpages/mockServiceWorker.js 로 감
    options: { scope: base },
  },
  onUnhandledRequest: "bypass",
};
